<?php
if(!isset($pdo))require_once __DIR__.'/config/database.php';$counts=[];foreach(['menunggu_verifikasi','diproses','dikirim','selesai'] as $st){$s=$pdo->prepare('SELECT COUNT(*) FROM pesanan WHERE status=:status');$s->execute(['status'=>$st]);$counts[]=(int)$s->fetchColumn();}$orders=$pdo->query("SELECT p.*,u.nama,u.username,b.bukti_pembayaran,b.status_tf FROM pesanan p JOIN `user` u ON u.id_user=p.id_user LEFT JOIN pembayaran b ON b.id_pembayaran=(SELECT MAX(id_pembayaran) FROM pembayaran WHERE id_pesanan=p.id_pesanan) ORDER BY p.id_pesanan DESC")->fetchAll();?><div class="admin-heading"><h1>Transaksi &amp; Pesanan</h1></div><div class="stats-grid"><div class="stat-card warning"><small>MENUNGGU VERIFIKASI</small><strong><?=$counts[0]?></strong></div><div class="stat-card"><small>DIPROSES</small><strong><?=$counts[1]?></strong></div><div class="stat-card"><small>DIKIRIM</small><strong><?=$counts[2]?></strong></div><div class="stat-card"><small>SELESAI</small><strong><?=$counts[3]?></strong></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Pelanggan</th><th>Produk</th><th>Total</th><th>Bukti</th><th>Bayar</th><th>Pesanan</th><th>Aksi</th></tr></thead><tbody><?php foreach($orders as $o):$items=json_decode((string)$o['items_json'],true)?:[['nama'=>'Produk','jumlah'=>$o['jumlah_produk']]];?><tr><td><?=e($o['nama']??$o['username'])?></td><td><?php $n=[];foreach($items as $i)$n[]=(int)$i['jumlah'].'x '.e($i['nama']);echo implode(', ',$n);?></td><td><?=formatRupiah($o['total'])?></td><td><?php if($o['bukti_pembayaran']):?><a class="promo-link" target="_blank" href="<?=e($o['bukti_pembayaran'])?>">Lihat bukti</a><?php else:?>—<?php endif;?></td><td><span class="status-badge <?=$o['status_tf']==='diterima'?'status-green':'status-orange'?>"><?=strtoupper($o['status_tf']??'MENUNGGU')?></span></td><td><span class="status-badge <?=orderStatusClass($o['status'])?>"><?=orderStatusLabel($o['status'])?></span></td><td><?php if(in_array($o['status'],['menunggu_verifikasi','diproses','dikirim'],true)):?><form class="action-row" method="post" action="verifikasi_transaksi.php"><input type="hidden" name="id_pesanan" value="<?=$o['id_pesanan']?>"><button class="icon-button" name="aksi" value="terima" aria-label="Verifikasi">✓</button><button class="icon-button danger" name="aksi" value="tolak" aria-label="Tolak">×</button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table></div>